// Gshare branch predictor with 128-entry saturating PHT, hashed into a 7-bit
// index. This predictor can be used for both infrequently taken branches (like
// indirect jumps) and frequently taken branches (like loops).
module TopModule(
    input  clk,
    input  areset,
    // Prediction interface: asks the predictor for the branch prediction for a
    // given pc.
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    // Training interface: tells the predictor the actual branch outcome and
    // whether it was a misprediction. Updates the PHT accordingly.
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] pht [0:127];
    reg [6:0] history;
    wire [6:0] hash = predict_pc ^ history;
    reg [1:0] pred;
    reg [1:0] next_pred;
    reg [6:0] next_history;
    always @(*) begin
        pred = pht[hash];
        next_pred = pht[hash] + (predict_taken ? 2'd1 : 2'd0) - (predict_taken ? 2'd0 : 2'd1);
        next_history = (predict_taken ? history + 1 : history - 1);
    end
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'd1;
            history <= 7'd0;
        end else begin
            if (predict_valid) begin
                predict_taken <= (pred >= 2'd2);
                predict_history <= history;
            end
            if (train_valid) begin
                pht[hash] <= next_pred;
                if (train_mispredicted) history <= train_history;
                else history <= next_history;
            end
        end
    end
endmodule

