// hashed index, 7-bit global history. Predicts only in the fetch stage
// (i.e., immediately after the branch is fetched, before it is decoded).
module TopModule(input clk, input areset,
                 input predict_valid, input [6:0] predict_pc, output reg predict_taken, output reg [6:0] predict_history,
