        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) counter[i] <= 2'b10;
            history <= 7'd0;
        end else begin
            if (predict_valid) begin
                predict_taken <= counter[{history, predict_pc}][1];
                predict_history <= history;
            end
            if (train_valid) begin
                counter[{train_history, train_pc}][1] <= train_taken;
                counter[{train_history, train_pc}][0] <= ~train_taken;
                if (train_mispredicted) history <= train_history;
            end
            if (predict_valid & ~train_valid) history <= {history[5:0], predict_taken};
